package net.bakaar.authz.common;

import io.hypersistence.tsid.TSID;

/**
 * Primary keys are generated by the application, never by the database: time-sorted 64-bit TSIDs stored as BIGINT.
 * <p>
 * Each running instance must use a distinct node id to rule out collisions: set {@code TSID_NODE} (and
 * {@code TSID_NODE_COUNT}, default 1024) as env vars, or {@code tsid.node} / {@code tsid.node.count} as system
 * properties. Without them a random node id is picked at startup.
 */
public final class Ids {

    private Ids() {
    }

    public static long next() {
        return TSID.Factory.getTsid().toLong();
    }
}
